; Jump table, symbol table and the embedded source area (generated by
; tools/gen.py). The source area is read from disk at boot.

SYM_ADDR    equ 0
SYM_SIZE    equ 8
SYM_SLOT    equ 16
SYM_SRC     equ 20
SYM_NAME    equ 32
SYM_RECORD  equ 64

SRC_HDR_LENGTH equ 8

%include "build/gen/jt.inc"
%include "build/gen/symtab.inc"
%include "build/gen/labels.inc"

; name: src_load
; in:   none
; out:  src_area = the source area read from disk, 0 if it is missing or bad
; clobbers: caller-saved
src_load:
    push rbx
    mov edi, 1
    call page_alloc                 ; first sector, to learn the length
    jc .none
    mov rbx, rax
    mov edi, SRC_LBA
    mov esi, 1
    mov rdx, rbx
    call ata_read
    jc .bad
    cmp dword [rbx], "VSRC"
    jne .bad
    mov edi, [rbx + SRC_HDR_LENGTH]
    cmp edi, SRC_SECTORS * 512
    ja .bad
    mov [rel src_length], rdi
    mov rdi, rbx
    mov esi, 1
    call page_free
    mov rdi, [rel src_length]
    add rdi, PAGE_SIZE - 1
    shr rdi, 12
    call page_alloc
    jc .none
    mov rbx, rax
    mov rdi, SRC_LBA                ; whole area, up to 256 sectors per read
    mov rsi, [rel src_length]
    add rsi, 511
    shr rsi, 9
    mov rdx, rbx
.chunk:
    push rdi
    push rsi
    push rdx
    sub rsp, 8
    cmp rsi, 256
    jbe .last
    mov esi, 256
.last:
    call ata_read
    lea rsp, [rsp + 8]              ; keeps CF
    pop rdx
    pop rsi
    pop rdi
    jc .read_failed
    add rdi, 256
    add rdx, 256 * 512
    sub rsi, 256
    jg .chunk
    mov [rel src_area], rbx
    lea rdi, [rel src_msg_loaded]
    call kputs
    mov rdi, [rel src_length]
    call [rel jt_kput_dec]
    lea rdi, [rel src_msg_bytes]
    call kputs
    pop rbx
    ret
.read_failed:
    mov rdi, rbx
    mov rsi, [rel src_length]
    add rsi, PAGE_SIZE - 1
    shr rsi, 12
    call page_free
    jmp .none
.bad:
    mov rdi, rbx
    mov esi, 1
    call page_free
.none:
    lea rdi, [rel src_msg_missing]
    call kputs
    pop rbx
    ret

; name: sym_dump
; in:   none
; out:  "[sym] name address size slot src" per function, then the first line
;       of each embedded function's source as "[src] name: line"
; clobbers: caller-saved
sym_dump:
    push rbx
    push r12
    sub rsp, 8
    lea rbx, [rel sym_table]
    xor r12d, r12d
.record:
    lea rdi, [rel sym_msg_sym]
    call kputs
    lea rdi, [rbx + SYM_NAME]
    call kputs
    mov edi, ' '
    call kputc
    mov rdi, [rbx + SYM_ADDR]
    call kput_hex
    mov edi, ' '
    call kputc
    mov rdi, [rbx + SYM_SIZE]
    call [rel jt_kput_dec]
    mov edi, ' '
    call kputc
    movsxd rdi, dword [rbx + SYM_SLOT]
    call sym_put_signed
    mov edi, ' '
    call kputc
    movsxd rdi, dword [rbx + SYM_SRC]
    call sym_put_signed
    mov edi, 10
    call kputc
    add rbx, SYM_RECORD
    inc r12d
    cmp r12d, SYM_COUNT
    jb .record

    cmp qword [rel src_area], 0
    je .done
    lea rbx, [rel sym_table]
    xor r12d, r12d
.source:
    movsxd rax, dword [rbx + SYM_SRC]
    test rax, rax
    js .next_source
    lea rdi, [rel sym_msg_src]
    call kputs
    lea rdi, [rbx + SYM_NAME]
    call kputs
    lea rdi, [rel sym_msg_colon]
    call kputs
    movsxd rax, dword [rbx + SYM_SRC]
    mov rsi, [rel src_area]
    add rsi, rax
.char:
    movzx edi, byte [rsi]
    cmp edi, 10
    je .line_end
    push rsi
    sub rsp, 8
    call kputc
    add rsp, 8
    pop rsi
    inc rsi
    jmp .char
.line_end:
    mov edi, 10
    call kputc
.next_source:
    add rbx, SYM_RECORD
    inc r12d
    cmp r12d, SYM_COUNT
    jb .source
.done:
    add rsp, 8
    pop r12
    pop rbx
    ret

; name: sym_put_signed
; in:   rdi = signed value
; out:  decimal on the log, with '-' when negative
; clobbers: caller-saved
sym_put_signed:
    test rdi, rdi
    jns .positive
    push rdi
    mov edi, '-'
    call kputc
    pop rdi
    neg rdi
.positive:
    jmp [rel jt_kput_dec]

src_msg_loaded  db "[src] source area loaded, ", 0
src_msg_bytes   db " bytes", 10, 0
src_msg_missing db "[src] source area missing", 10, 0
sym_msg_sym     db "[sym] ", 0
sym_msg_src     db "[src] ", 0
sym_msg_colon   db ": ", 0

section .bss
alignb 8
src_area   resq 1
src_length resq 1
section .text
